def apply_operation(n):
    if n < 0:
        raise ValueError("Input must be non-negative")
    if n == 0:
        return 0 # Although we start with n >= 1

    d = n % 10
    n_prime = n // 10
    n_new = n_prime + 3 * d
    return n_new

def analyze_sequence(start_n):
    sequence = []
    history = {} # {number: step_index}
    current_n = start_n

    # We can run for a reasonable number of steps to ensure we find a cycle/stable point.
    # Since the numbers generally shrink or stay within a manageable range (e.g., if n=99, new=9+27=36; if n=19, new=1+27=28), 
    # cycles should appear relatively quickly. Let's set a generous limit, say 1000 steps.
    max_steps = 1000

    for step in range(max_steps):
        if current_n in history:
            start_step = history[current_n]
            cycle_length = step - start_step
            return {
                "type": "cycle",
                "start_value": current_n,
                "cycle_start_index": start_step,
                "cycle_length": cycle_length,
                "full_sequence": sequence[:] # Sequence up to the first repetition
            }

        history[current_n] = step
        sequence.append(current_n)

        next_n = apply_operation(current_n)

        if next_n == current_n and step > 0: # Stable point detected (and it's not the starting point if start_n was stable)
            return {
                "type": "stable",
                "stable_value": current_n,
                "full_sequence": sequence[:]
            }

        current_n = next_n

    return {
        "type": "limit_reached",
        "full_sequence": sequence,
        "message": "Did not find a cycle or stable point within the limit."
    }

results = {}
for n in range(1, 101):
    results[n] = analyze_sequence(n)

# Prepare output for notes.md
output = "--- Sequence Analysis for n=1 to 100 ---\n"
for n in sorted(results.keys()):
    res = results[n]
    output += f"\n[Starting N = {n}]\n"

    if res['type'] == 'stable':
        output += f"  -> Stable Point Found: {res['stable_value']}\n"
        output += f"  -> Full Sequence: {res['full_sequence']}\n"
    elif res['type'] == 'cycle':
        output += f"  -> Cycle Found: Value {res['start_value']} repeated.\n"
        output += f"  -> Cycle Starts at Step {res['cycle_start_index']} (Value: {res['start_value']})\n"
        output += f"  -> Cycle Length: {res['cycle_length']}\n"
        # Show the sequence up to the point the cycle starts repeating
        sequence_str = ", ".join(map(str, res['full_sequence']))
        output += f"  -> Sequence (up to cycle start): {sequence_str}\n"
    else:
        output += f"  -> Analysis Limit Reached.\n"

print(output)
